  native=page.locator('[data-lumiverse-html-island] .phone');native_header=native.locator('.contact').evaluate('e=>({font:getComputedStyle(e).fontFamily,size:getComputedStyle(e).fontSize,color:getComputedStyle(e).color,display:getComputedStyle(e.parentElement).display})')
  page.locator('#launch').click();shell=page.locator('.ss-story-theater-dialog .shell');stage=shell.locator('.stage');count=shell.locator('[data-count]');phone=stage.locator('.phone');messages=phone.locator('.messages');expect(count).to_have_text('1 / 2');expect(phone).to_be_visible()
  assert phone.locator('.contact').evaluate('e=>({font:getComputedStyle(e).fontFamily,size:getComputedStyle(e).fontSize,color:getComputedStyle(e).color,display:getComputedStyle(e.parentElement).display})')==native_header
