  assert phone.locator('[onclick],[data-lumiverse-regex-action],script,iframe').count()==0
  assert phone.locator('.visually-hidden').count()==1 and not phone.locator('.visually-hidden').is_visible()
  assert phone.locator('header').evaluate('e=>e.getBoundingClientRect().height')<100
  assert phone.locator('.bubble').first.evaluate('e=>getComputedStyle(e).backgroundColor')=='rgb(38, 38, 38)'
  # Native disclosure and CSS-only checkbox toggles must survive sanitization.
  details=phone.locator('.local-details');summary=details.locator('summary');toggle=phone.locator('.local-check');label=phone.locator('label[for=show-extra]');extra=phone.locator('.local-extra');assert details.get_attribute('open') is None;assert not extra.is_visible()
  summary.click();expect(details).to_have_attribute('open','');label.click();expect(toggle).to_be_checked();expect(extra).to_be_visible();expect(count).to_have_text('1 / 2')
  page.evaluate('theater.render()');expect(details).to_have_attribute('open','');expect(toggle).to_be_checked();assert page.evaluate('!document.querySelector("[data-lumiverse-html-island]").shadowRoot.querySelector(".local-details").open&&!document.querySelector("[data-lumiverse-html-island]").shadowRoot.querySelector(".local-check").checked');assert page.evaluate('calls.length===0&&!window.bad')
  summary.focus();page.keyboard.press('Space');assert details.get_attribute('open') is None;label.click();expect(toggle).not_to_be_checked();expect(count).to_have_text('1 / 2')
  assert messages.evaluate('e=>e.scrollHeight>e.clientHeight')
  messages.hover();page.mouse.wheel(0,220);page.wait_for_timeout(300);assert messages.evaluate('e=>e.scrollTop')>100
  expect(count).to_have_text('1 / 2')
