  if width<720:
   # Trusted touch drag through Chromium input, not a synthetic DOM event.
   box=messages.bounding_box();x=box['x']+box['width']/2;y=box['y']+box['height']*.8;session=page.context.new_cdp_session(page)
   session.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':x,'y':y}]})
   for i in range(1,9):session.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x,'y':y-i*15}]});page.wait_for_timeout(25)
   session.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});page.wait_for_timeout(350);assert messages.evaluate('e=>e.scrollTop')>saved
   expect(count).to_have_text('1 / 2')
